package com.aitrading.journal;
import com.aitrading.ai.AiFailure;import com.aitrading.api.*;import com.aitrading.auth.UserPrincipal;import com.aitrading.strategy.StrategyService;import jakarta.servlet.http.HttpServletRequest;import java.util.Map;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/journal/{id}/evaluations") public class JournalEvaluationController {private final JournalEvaluationStore store;private final JournalEvaluationService service;public JournalEvaluationController(JournalEvaluationStore s,JournalEvaluationService v){store=s;service=v;}@PostMapping public JournalEvaluationStore.Evaluation start(@AuthenticationPrincipal UserPrincipal u,@PathVariable String id,@RequestBody JournalEvaluationStore.Start body){return service.start(u,StrategyService.id(id),body);}@GetMapping public ResponseEntity<?> latest(@AuthenticationPrincipal UserPrincipal u,@PathVariable String id){var e=store.latest(u,StrategyService.id(id));return e==null?ResponseEntity.noContent().build():ResponseEntity.ok(e);}@GetMapping("/{requestId}") public JournalEvaluationStore.Evaluation get(@AuthenticationPrincipal UserPrincipal u,@PathVariable String id,@PathVariable String requestId){return store.get(u,StrategyService.id(id),StrategyService.id(requestId));}@PostMapping("/{requestId}/cancel") public JournalEvaluationStore.Evaluation cancel(@AuthenticationPrincipal UserPrincipal u,@PathVariable String id,@PathVariable String requestId,@RequestBody Map<String,Object> ignored){return store.cancel(u,StrategyService.id(id),StrategyService.id(requestId));}@ExceptionHandler(AiFailure.class) public ResponseEntity<?> unavailable(HttpServletRequest request,AiFailure failure){return ResponseEntity.status(503).body(Map.of("code",failure.code().name(),"requestId",ApiErrors.requestId(request)));}}
